var r = await machine.exec({ command: `cd /tmp && python3 - <<'EOF'
import json
alld=json.load(open('/tmp/alld.json'))
tick=['NVDA','AAPL','WMT','AMZN','META']
sa={}
for t in tick:
    d=json.load(open(f'/tmp/sa_{t.lower()}.json'))['data']
    sa[t]={x['t']:x for x in d}
W0,W1='2025-03-19','2025-04-16'
H0,H1='2025-01-02','2025-06-30'
diffs=0
for t in tick:
    print('====',t)
    for x in alld[t]:
        if not (H0<=x['date']<=H1): continue
        s=sa[t].get(x['date'])
        if s is None: print('  MISSING in sa:', x['date']); continue
        d=[]
        for k,kk in (('open','o'),('high','h'),('low','l'),('close','c')):
            if abs(x[k]-s[kk])>0.015: d.append(f"{k}: Y={x[k]:.4f} S={s[kk]:.4f}")
        if abs(x['volume']-s['v'])/max(s['v'],1)>0.02: d.append(f"vol: Y={x['volume']} S={s['v']}")
        if d:
            diffs+=1
            inw = 'IN-WINDOW' if W0<=x['date']<=W1 else ''
            print('  ',x['date'], inw, ' | '.join(d))
print('total differing days:',diffs)
EOF` })
